    [Theory]
    [InlineData("test/foo.c")]                       // test/ top-level (node, express, pytorch, go, k8s, llvm, etc.)
    [InlineData("spec/user_spec.rb")]                // spec/ top-level (RSpec: mastodon, discourse)
