    [InlineData("unittests/foo.cpp")]                // unittests/ (llvm)
    [InlineData("integration-test/src/Foo.java")]    // -test suffix dir (spring-boot)
    [InlineData("test-support/Helper.kt")]           // test- prefix dir (spring-boot)
