    [InlineData("atest/b/code.cs")]                  // "atest" is not exact match "test"
    [InlineData("testa/b/code.cs")]                  // "testa" is not exact match
    public void IsTestRelated_SegmentNoFalsePrefixSuffix_ReturnsFalse(string path)
    {
        Assert.False(TestPathClassifier.IsTestRelated(path, []));
    }
}

using VisualRelay.Domain;

namespace VisualRelay.Core.Execution;

/// <summary>
/// Repo-agnostic test-path classifier.  Replaces the old 4-rule private
/// <c>IsTestFile</c> heuristic with a layered design: built-in directory-segment
/// + filename rules (covering the 40-repo survey), plus an optional
/// <c>testPaths</c> glob override from <see cref="RelayConfig"/>.
///
/// Two predicates:
/// <list type="bullet">
///   <item><see cref="IsTestRelated"/> — for impl-exclusion gates
///       (EarlyImplementationDetector, CodeChangeGate).</item>
///   <item><see cref="IsRunnableTestFile"/> — additionally filters out
///       non-code extensions for <c>{files}</c> expansion.</item>
/// </list>
/// </summary>
public static class TestPathClassifier
{
    /// <summary>
    /// Extensions that are docs / config / fixture data — not runnable test code.
    /// A test-related path with one of these extensions is still test-related for
    /// impl-exclusion gates but excluded from <c>{files}</c> expansion.
    /// </summary>
    internal static readonly HashSet<string> NonCodeExtensions = new(StringComparer.OrdinalIgnoreCase)
    { ".md", ".txt", ".json", ".yaml", ".yml", ".toml", ".csv" };

    /// <summary>
    /// Extensions for which a PascalCase <c>…Test</c>/<c>…Tests</c>/<c>…Spec</c>
    /// suffix on the filename (sans extension) signals a test file.  Restricted
    /// to the JVM / .NET / PHP / Swift ecosystems where this convention is
    /// universal; other ecosystems use different naming (e.g. <c>test_*.py</c>,
    /// <c>*_test.go</c>, <c>*.test.ts</c>) that are covered by the other rules.
    /// </summary>
    private static readonly HashSet<string> PascalTestExtensions = new(StringComparer.OrdinalIgnoreCase)
    { ".java", ".kt", ".cs", ".php", ".swift" };

    /// <summary>
    /// Directory-segment names that always indicate a test directory.
    /// Case-insensitive exact match against each <c>/</c>-delimited segment.
    /// </summary>
    private static readonly HashSet<string> TestDirNames = new(StringComparer.OrdinalIgnoreCase)
    {
        "test", "tests", "spec", "specs", "t", "__tests__", "unittests",
        "testdata", "test_suite", "testfixtures", "htesting"
    };

    /// <summary>
    /// Returns true when <paramref name="path"/> is test-related per the
    /// built-in heuristics or <paramref name="testPaths"/> globs.
    /// Normalises backslashes so Windows paths match.
    /// </summary>
    public static bool IsTestRelated(string path, IReadOnlyList<string> testPaths)
    {
        var normalized = path.Replace('\\', '/');

        // ── Directory-segment rules ────────────────────────────────
        foreach (var segment in normalized.Split('/'))
        {
            if (TestDirNames.Contains(segment))
                return true;

            if (segment.StartsWith("test-", StringComparison.OrdinalIgnoreCase) ||
                segment.StartsWith("tests-", StringComparison.OrdinalIgnoreCase) ||
                segment.StartsWith("test_", StringComparison.OrdinalIgnoreCase))
                return true;

            if (segment.EndsWith("-test", StringComparison.OrdinalIgnoreCase) ||
                segment.EndsWith("-tests", StringComparison.OrdinalIgnoreCase) ||
                segment.EndsWith("_test", StringComparison.OrdinalIgnoreCase) ||
                segment.EndsWith("_tests", StringComparison.OrdinalIgnoreCase))
                return true;
        }

        // ── Filename rules ─────────────────────────────────────────
        var fileName = Path.GetFileName(path);
        var nameWithoutExt = Path.GetFileNameWithoutExtension(fileName);

        if (fileName.Contains(".tests.", StringComparison.OrdinalIgnoreCase))
            return true;
        if (fileName.Contains(".spec.", StringComparison.OrdinalIgnoreCase))
            return true;
        if (fileName.Contains(".test.", StringComparison.OrdinalIgnoreCase))
            return true;

        if (nameWithoutExt.EndsWith("_test", StringComparison.OrdinalIgnoreCase))
            return true;
        if (nameWithoutExt.StartsWith("test_", StringComparison.OrdinalIgnoreCase))
            return true;
        if (nameWithoutExt.EndsWith("-test", StringComparison.OrdinalIgnoreCase))
            return true;
        if (nameWithoutExt.EndsWith("_spec", StringComparison.OrdinalIgnoreCase))
            return true;

        // PascalCase suffix only for ecosystem extensions
        var ext = Path.GetExtension(fileName);
        if (PascalTestExtensions.Contains(ext))
        {
            if (nameWithoutExt.EndsWith("Test", StringComparison.Ordinal) ||
                nameWithoutExt.EndsWith("Tests", StringComparison.Ordinal) ||
                nameWithoutExt.EndsWith("Spec", StringComparison.Ordinal))
                return true;
        }

        // ── Config globs (additive) ────────────────────────────────
        if (testPaths.Count > 0)
        {
            foreach (var glob in testPaths)
            {
                if (RelayDriver.MatchesGuardGlob(normalized, glob))
                    return true;
            }
        }

        return false;
    }

    /// <summary>
    /// Returns true when <paramref name="path"/> is both test-related
    /// (<see cref="IsTestRelated"/>) AND has a runnable-code extension
    /// (not in <see cref="NonCodeExtensions"/> and not extensionless).
    /// Use for <c>{files}</c> expansion in targeted test commands.
    /// </summary>
    public static bool IsRunnableTestFile(string path, IReadOnlyList<string> testPaths)
    {
        if (!IsTestRelated(path, testPaths))
            return false;

        var ext = Path.GetExtension(path);
        if (ext.Length == 0)
            return false;

        return !NonCodeExtensions.Contains(ext);
    }
}

